WITH lines AS (SELECT id, effective_from, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) li AS element) SELECT currency, DATE_TRUNC('YEAR', effective_from) AS year_start, CASE WHEN element >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows, COUNT_IF(currency = 'USD') AS usd_events, APPROX_PERCENTILE(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, COUNT(*) AS num_rows FROM lines GROUP BY GROUPING SETS ((currency, DATE_TRUNC('YEAR', effective_from), CASE WHEN element >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END), (currency, DATE_TRUNC('YEAR', effective_from)), (currency))
